-- Recoverable idempotency claims (T367; constitution XX.2), generated by Prisma from schema.prisma:
-- a claim token and a lease, so an abandoned claim can be taken over, and the time the request's
-- first write committed, set in that write's own transaction, so a retry never runs it twice.
-- AlterTable
ALTER TABLE "IdempotencyKey" ADD COLUMN     "claimToken" TEXT NOT NULL DEFAULT (gen_random_uuid())::text,
ADD COLUMN     "committedAt" TIMESTAMP(3),
ADD COLUMN     "lockedUntil" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
